class Account(BaseModel):
    """For new integrations, we recommend using the [Accounts v2 API](/api/v2/core/accounts),
    in place of /v1/accounts and /v1/customers to represent a user.

    This is an object representing a Stripe account. You can retrieve it to see
    properties on the account like its current requirements or if the account is
    enabled to make live charges or receive payouts.

    For accounts where
    [controller.requirement_collection](/api/accounts/object#account_object-controller-
    requirement_collection)
    is `application`, which includes Custom accounts, the properties below are always
    returned.

    For accounts where
    [controller.requirement_collection](/api/accounts/object#account_object-controller-
    requirement_collection)
    is `stripe`, which includes Standard and Express accounts, some properties are only
    returned
    until you create an [Account Link](/api/account_links) or [Account
    Session](/api/account_sessions)
    to start Connect Onboarding. Learn about the [differences between
    accounts](/connect/accounts).
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # Business information about the account.
    business_profile: AccountBusinessProfile | None = None

    # The business type.
    business_type: Literal["company", "government_entity", "individual", "non_profit"] | None = None
    capabilities: AccountCapabilities | None = None

    # Whether the account can process charges.
    charges_enabled: bool | None = None
    company: LegalEntityCompany | None = None
    controller: AccountUnificationAccountController | None = None

    # The account's country.
    country: str | None = None

    # Time at which the account was connected. Measured in seconds since the Unix epoch.
    created: int | None = None

    # Three-letter ISO currency code representing the default currency for the account. This
    # must be a currency that [Stripe supports in the account's
    # country](https://stripe.com/docs/payouts).
    default_currency: str | None = None

    # Whether account details have been submitted. Accounts with Stripe Dashboard access, which
    # includes Standard accounts, cannot receive payouts before this is true. Accounts where
    # this is false should be directed to [an onboarding flow](/connect/onboarding) to finish
    details_submitted: bool | None = None

    # An email address associated with the account. It's not used for authentication and Stripe
    # doesn't market to this field without explicit approval from the platform.
    email: str | None = None

    # External accounts (bank accounts and debit cards) currently attached to this account.
    # External accounts are only returned for requests where `controller[is_controller]` is
    # true.
    external_accounts: AccountExternalAccounts | None = None
    future_requirements: AccountFutureRequirements | None = None

    # The groups associated with the account.
    groups: AccountGroupMembership | None = None

    # Unique identifier for the object.
    id: str

    # This is an object representing a person associated with a Stripe account. A platform can
    # only access a subset of data in a person for an account where
    # [account.controller.requirement_collection](/api/accounts/object#account_object-
    individual: Person | None = None

    # Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an
    # object. This can be useful for storing additional information about the object in a
    # structured format.
    metadata: dict[str, str] | None = None

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["account"]

    # Whether the funds in this account can be paid out.
    payouts_enabled: bool | None = None
    requirements: AccountRequirements | None = None

    # Options for customizing how the account functions within Stripe.
    settings: AccountSettings | None = None
    tos_acceptance: AccountTosAcceptance | None = None

    # The Stripe account type. Can be `standard`, `express`, `custom`, or `none`.
    type_: Literal["custom", "express", "none", "standard"] | None = Field(None, alias="type")


class AccountExternalAccounts(BaseModel):
    """External accounts (bank accounts and debit cards) currently attached to this account.
    External accounts are only returned for requests where `controller[is_controller]` is
    true.
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # The list contains all external accounts that have been attached to the Stripe account.
    # These may be bank accounts or cards.
    data: list[ExternalAccount]

    # True if this list has another page of items after this one that can be fetched.
    has_more: bool

    # String representing the object's type. Objects of the same type share the same value.
    # Always has the value `list`.
    object: Literal["list"]

    # The URL where this list can be accessed.
    url: str


