class ApplicationFee(BaseModel):
    """When you collect a transaction fee on top of a charge made for your user
    (using [Connect](https://docs.stripe.com/connect)), an `Application Fee` object is
    created in
    your account. You can list, retrieve, and refund application fees.

    Related guide: [Collecting application fees](https://docs.stripe.com/connect/direct-
    charges#collect-fees)
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # ID of the Stripe account this fee was taken from.
    account: str | Account

    # Amount earned, in cents (or local equivalent).
    amount: int

    # Amount in cents (or local equivalent) refunded (can be less than the amount attribute on
    # the fee if a partial refund was issued)
    amount_refunded: int

    # ID of the Connect application that earned the fee.
    application: str | Application

    # Balance transaction that describes the impact of this collected application fee on your
    # account balance (not including refunds).
    balance_transaction: str | BalanceTransaction | None

    # ID of the charge that the application fee was taken from.
    charge: str | Charge

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # Polymorphic source of the application fee. Includes the ID of the object the application
    # fee was created from.
    fee_source: PlatformEarningFeeSource | None

    # Unique identifier for the object.
    id: str

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["application_fee"]

    # ID of the corresponding charge on the platform account, if this fee was the result of a
    # charge using the `destination` parameter.
    originating_transaction: str | Charge | None

    # Whether the fee has been fully refunded. If the fee is only partially refunded, this
    # attribute will still be false.
    refunded: bool

    # A list of refunds that have been applied to the fee.
    refunds: ApplicationFeeRefunds


class ApplicationFeeRefunds(BaseModel):
    """A list of refunds that have been applied to the fee."""

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

