class AutomaticTax(BaseModel):
    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # If Stripe disabled automatic tax, this enum describes why.
    disabled_reason: (
        Literal["finalization_requires_location_inputs", "finalization_system_error"] | None
    )

    # Whether Stripe automatically computes tax on this invoice. Note that incompatible invoice
    # items (invoice items with manually specified [tax
    # rates](https://docs.stripe.com/api/tax_rates), negative amounts, or
    enabled: bool

    # The account that's liable for tax. If set, the business address and tax registrations
    # required to perform the tax calculation are loaded from this account. The tax transaction
    # is returned in the report of the connected account.
    liability: ConnectAccountReference | None

    # The tax provider powering automatic tax.
    provider: str | None

    # The status of the most recent automated tax calculation for this invoice.
    status: Literal["complete", "failed", "requires_location_inputs"] | None


class BalanceTransaction(BaseModel):
    """Balance transactions represent funds moving through your Stripe account.
    Stripe creates them for every type of transaction that enters or leaves your Stripe
    account balance.

    Related guide: [Balance transaction types](https://docs.stripe.com/reports/balance-
    transaction-types)
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # Gross amount of this transaction (in cents (or local equivalent)). A positive value
    # represents funds charged to another party, and a negative value represents funds sent to
    # another party.
    amount: int

    # The date that the transaction's net funds become available in the Stripe balance.
    available_on: int

    # The balance that this transaction impacts.
    balance_type: Literal["issuing", "payments", "refund_and_dispute_prefunding", "risk_reserved"]

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # An arbitrary string attached to the object. Often useful for displaying to users.
    description: str | None

    # If applicable, this transaction uses an exchange rate. If money converts from currency A
    # to currency B, then the `amount` in currency A, multiplied by the `exchange_rate`, equals
    # the `amount` in currency B. For example, if you charge a customer 10.00 EUR, the
    exchange_rate: float | None

    # Fees (in cents (or local equivalent)) paid for this transaction. Represented as a positive
    # integer when assessed.
    fee: int

    # Detailed breakdown of fees (in cents (or local equivalent)) paid for this transaction.
    fee_details: list[Fee]

    # Unique identifier for the object.
    id: str

    # Net impact to a Stripe balance (in cents (or local equivalent)). A positive value
