class Customer(BaseModel):
    """This object represents a customer of your business. Use it to [create recurring
    charges](https://docs.stripe.com/invoicing/customer), [save
    payment](https://docs.stripe.com/payments/save-during-payment) and contact
    information,
    and track payments that belong to the same customer.
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # The customer's billing address.
    address: Address | None = None

    # The current balance, if any, that's stored on the customer in their default currency. If
    # negative, the customer has credit to apply to their next invoice. If positive, the
    # customer has an amount owed that's added to their next invoice. The balance only considers
    balance: int | None = None

    # The customer's business name.
    business_name: str | None = None

    # The current funds being held by Stripe on behalf of the customer. You can apply these
    # funds towards payment intents when the source is "cash_balance". The
    # `settings[reconciliation_mode]` field describes if these funds apply to these payment
    cash_balance: CashBalance | None = None

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO code for the currency](https://stripe.com/docs/currencies) the customer
    # can be charged in for recurring billing purposes.
    currency: str | None = None

    # The ID of an Account representing a customer. You can use this ID with any v1 API that
    # accepts a customer_account parameter.
    customer_account: str | None = None

    # ID of the default payment source for the customer. If you use payment methods created
    # through the PaymentMethods API, see the [invoice_settings.default_payment_method](https://
    # docs.stripe.com/api/customers/object#customer_object-invoice_settings-
    default_source: str | PaymentSource | None

    # Tracks the most recent state change on any invoice belonging to the customer. Paying an
    # invoice or marking it uncollectible via the API will set this field to false. An automatic
    # payment failure or passing the `invoice.due_date` will set this field to `true`. If an
    delinquent: bool | None = None

    # An arbitrary string attached to the object. Often useful for displaying to users.
    description: str | None

    # Describes the current discount active on the customer, if there is one.
    discount: Discount | None = None

    # The customer's email address.
    email: str | None

    # Unique identifier for the object.
    id: str

    # The customer's individual name.
    individual_name: str | None = None

    # The current multi-currency balances, if any, that's stored on the customer. If positive in
    # a currency, the customer has a credit to apply to their next invoice denominated in that
    # currency. If negative, the customer has an amount owed that's added to their next invoice
    invoice_credit_balance: dict[str, int] | None = None

    # The prefix for the customer used to generate unique invoice numbers.
    invoice_prefix: str | None = None
    invoice_settings: InvoiceSettingCustomerSetting | None = None

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an
    # object. This can be useful for storing additional information about the object in a
    # structured format.
    metadata: dict[str, str] | None = None

    # The customer's full name or business name.
    name: str | None = None

    # The suffix of the customer's next invoice number (for example, 0001). When the account
    # uses account level sequencing, this parameter is ignored in API requests and the field
    # omitted in API responses.
    next_invoice_sequence: int | None = None

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["customer"]

    # The customer's phone number.
    phone: str | None = None

    # The customer's preferred locales (languages), ordered by preference.
    preferred_locales: list[str] | None = None

    # Mailing and shipping address for the customer. Appears on invoices emailed to this
    # customer.
    shipping: Shipping | None

    # The customer's payment sources, if any.
    sources: CustomerSources | None = None

    # The customer's current subscriptions, if any.
    subscriptions: CustomerSubscriptions | None = None
    tax: CustomerTax | None = None

    # Describes the customer's tax exemption status, which is `none`, `exempt`, or `reverse`.
    # When set to `reverse`, invoice and receipt PDFs include the following text: **"Reverse
    # charge"**.
    tax_exempt: Literal["exempt", "none", "reverse"] | None = None

    # The customer's tax IDs.
    tax_ids: CustomerTaxIds | None = None

    # ID of the test clock that this customer belongs to.
    test_clock: str | TestHelpersTestClock | None = None


