class CustomerCashBalanceTransaction(BaseModel):
    """Customers with certain payments enabled have a cash balance, representing funds that
    were paid
    by the customer to a merchant, but have not yet been allocated to a payment. Cash
    Balance Transactions
    represent when funds are moved into or out of this balance. This includes funding by
    the customer, allocation
    to payments, and refunds to the customer.
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())
    adjusted_for_overdraft: (
        CustomerBalanceResourceCashBalanceTransactionResourceAdjustedForOverdraft | None
    ) = None
    applied_to_payment: (
        CustomerBalanceResourceCashBalanceTransactionResourceAppliedToPaymentTransaction | None
    ) = None

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # The customer whose available cash balance changed as a result of this transaction.
    customer: str | Customer

    # The ID of an Account representing a customer whose available cash balance changed as a
    # result of this transaction.
    customer_account: str | None

    # The total available cash balance for the specified currency after this transaction was
    # applied. Represented in the [smallest currency
    # unit](https://docs.stripe.com/currencies#zero-decimal).
    ending_balance: int
    funded: CustomerBalanceResourceCashBalanceTransactionResourceFundedTransaction | None = None

    # Unique identifier for the object.
    id: str

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # The amount by which the cash balance changed, represented in the [smallest currency
    # unit](https://docs.stripe.com/currencies#zero-decimal). A positive value represents funds
    # being added to the cash balance, a negative value represents funds being removed from the
    net_amount: int

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["customer_cash_balance_transaction"]
    refunded_from_payment: (
        CustomerBalanceResourceCashBalanceTransactionResourceRefundedFromPaymentTransaction | None
    ) = None
    transferred_to_balance: (
        CustomerBalanceResourceCashBalanceTransactionResourceTransferredToBalance | None
    ) = None

    # The type of the cash balance transaction. New types may be added in future. See [Customer
    # Balance](https://docs.stripe.com/payments/customer-balance#types) to learn more about
    # these types.
    type_: Literal[
        "adjusted_for_overdraft",
        "applied_to_payment",
        "funded",
        "funding_reversed",
        "refunded_from_payment",
        "return_canceled",
        "return_initiated",
        "transferred_to_balance",
        "unapplied_from_payment",
    ] = Field(alias="type")
    unapplied_from_payment: (
        CustomerBalanceResourceCashBalanceTransactionResourceUnappliedFromPaymentTransaction | None
    ) = None


