class Dispute(BaseModel):
    """A dispute occurs when a customer questions your charge with their card issuer.
    When this happens, you have the opportunity to respond to the dispute with
    evidence that shows that the charge is legitimate.

    Related guide: [Disputes and fraud](https://docs.stripe.com/disputes)
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # Disputed amount. Usually the amount of the charge, but it can differ (usually because of
    # currency fluctuation or because only part of the order is disputed).
    amount: int

    # List of zero, one, or two balance transactions that show funds withdrawn and reinstated to
    # your Stripe account as a result of this dispute.
    balance_transactions: list[BalanceTransaction]

    # ID of the charge that's disputed.
    charge: str | Charge

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # List of eligibility types that are included in `enhanced_evidence`.
    enhanced_eligibility_types: list[
        Literal["mastercard_compliance", "visa_compelling_evidence_3", "visa_compliance"]
    ]
    evidence: DisputeEvidence
    evidence_details: DisputeEvidenceDetails

    # Unique identifier for the object.
    id: str

    # Intended submission method for the dispute.
    intended_submission_method: (
        Literal["manual", "prefer_manual", "prefer_smart_disputes", "smart_disputes"] | None
    )

    # If true, it's still possible to refund the disputed payment. After the payment has been
    # fully refunded, no further funds are withdrawn from your Stripe account as a result of
    # this dispute.
    is_charge_refundable: bool

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an
    # object. This can be useful for storing additional information about the object in a
    # structured format.
    metadata: dict[str, str]

    # Network-dependent reason code for the dispute.
    network_reason_code: str | None = None

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["dispute"]

    # ID of the PaymentIntent that's disputed.
    payment_intent: str | PaymentIntent | None
    payment_method_details: DisputePaymentMethodDetails | None = None

    # Reason given by cardholder for dispute. Possible values are `bank_cannot_process`,
    # `check_returned`, `credit_not_processed`, `customer_initiated`, `debit_not_authorized`,
    # `duplicate`, `fraudulent`, `general`, `incorrect_account_details`, `insufficient_funds`,
    reason: str

    # The current status of a dispute. Possible values include:`warning_needs_response`,
    # `warning_under_review`, `warning_closed`, `needs_response`, `under_review`,
    # `appeal_needs_response`, `appeal_under_review`, `won`, `lost`, or `prevented`.
    status: Literal[
        "appeal_needs_response",
        "appeal_under_review",
        "lost",
        "needs_response",
        "prevented",
        "under_review",
        "warning_closed",
        "warning_needs_response",
        "warning_under_review",
        "won",
    ]


