class Invoice(BaseModel):
    """Invoices are statements of amounts owed by a customer, and are either
    generated one-off, or generated periodically from a subscription.

    They contain [invoice items](https://docs.stripe.com/api#invoiceitems), and proration
    adjustments
    that may be caused by subscription upgrades/downgrades (if necessary).

    If your invoice is configured to be billed through automatic charges,
    Stripe automatically finalizes your invoice and attempts payment. Note
    that finalizing the invoice,
    [when automatic](https://docs.stripe.com/invoicing/integration/automatic-advancement-
    collection), does
    not happen immediately as the invoice is created. Stripe waits
    until one hour after the last webhook was successfully sent (or the last
    webhook timed out after failing). If you (and the platforms you may have
    connected to) have no webhooks configured, Stripe waits one hour after
    creation to finalize the invoice.

    If your invoice is configured to be billed by sending an email, then based on your
    [email settings](https://dashboard.stripe.com/account/billing/automatic),
    Stripe will email the invoice to your customer and await payment. These
    emails can contain a link to a hosted page to pay the invoice.

    Stripe applies any customer credit on the account before determining the
    amount due for the invoice (i.e., the amount that will be actually
    charged). If the amount due for the invoice is less than Stripe's [minimum allowed
    charge
    per currency](/docs/currencies#minimum-and-maximum-charge-amounts), the
    invoice is automatically marked paid, and we add the amount due to the
    customer's credit balance which is applied to the next invoice.

    More details on the customer's credit balance are
    [here](https://docs.stripe.com/billing/customer/balance).

    Related guide: [Send invoices to
    customers](https://docs.stripe.com/billing/invoices/sending)
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # The country of the business associated with this invoice, most often the business creating
    # the invoice.
    account_country: str | None

    # The public name of the business associated with this invoice, most often the business
    # creating the invoice.
    account_name: str | None

    # The account tax IDs associated with the invoice. Only editable when the invoice is a
    # draft.
    account_tax_ids: list[str | TaxId | DeletedTaxId] | None

    # Final amount due at this time for this invoice. If the invoice's total is smaller than the
    # minimum charge amount, for example, or if there is account credit that can be applied to
    # the invoice, the `amount_due` may be 0. If there is a positive `starting_balance` for the
    amount_due: int

    # Amount that was overpaid on the invoice. The amount overpaid is credited to the customer's
    # credit balance.
    amount_overpaid: int

    # The amount, in cents (or local equivalent), that was paid.
    amount_paid: int

    # Amount, in cents (or local equivalent), that was paid on the invoice outside of Stripe.
    amount_paid_off_stripe: int | None = None

    # The difference between amount_due and amount_paid, in cents (or local equivalent).
    amount_remaining: int

    # This is the sum of all the shipping amounts.
    amount_shipping: int

    # ID of the Connect Application that created the invoice.
    application: str | Application | DeletedApplication | None

    # Number of payment attempts made for this invoice, from the perspective of the payment
    # retry schedule. Any payment attempt counts as the first attempt, and subsequently only
    # automatic retries increment the attempt count. In other words, manual payment attempts
    attempt_count: int

    # Whether an attempt has been made to pay the invoice. An invoice is not attempted until 1
    # hour after the `invoice.created` webhook, for example, so you might not want to display
    # that invoice as unpaid to your users.
    attempted: bool

    # Controls whether Stripe performs [automatic
    # collection](https://docs.stripe.com/invoicing/integration/automatic-advancement-
    # collection) of the invoice. If `false`, the invoice's state doesn't automatically advance
    auto_advance: bool | None = None
    automatic_tax: AutomaticTax

    # The time when this invoice is currently scheduled to be automatically finalized. The field
    # will be `null` if the invoice is not scheduled to finalize in the future. If the invoice
    # is not in the draft state, this field will always be `null` - see `finalized_at` for the
    automatically_finalizes_at: int | None

    # Indicates the reason why the invoice was created. * `manual`: Unrelated to a subscription,
    # for example, created via the invoice editor. * `subscription`: No longer in use. Applies
    # to subscriptions from before May 2018 where no distinction was made between updates,
    billing_reason: (
        Literal[
            "automatic_pending_invoice_item_invoice",
            "manual",
            "quote_accept",
            "subscription",
            "subscription_create",
            "subscription_cycle",
            "subscription_threshold",
            "subscription_update",
            "upcoming",
        ]
        | None
    )

    # Either `charge_automatically`, or `send_invoice`. When charging automatically, Stripe will
    # attempt to pay this invoice using the default source attached to the customer. When
    # sending an invoice, Stripe will email this invoice to the customer with payment
    collection_method: Literal["charge_automatically", "send_invoice"]

    # The confirmation secret associated with this invoice. Currently, this contains the
    # client_secret of the PaymentIntent that Stripe creates during invoice finalization.
    confirmation_secret: InvoicesResourceConfirmationSecret | None = None

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # Custom fields displayed on the invoice.
    custom_fields: list[InvoiceSettingCustomField] | None

    # The ID of the customer to bill.
    customer: str | Customer | DeletedCustomer | None

    # The ID of the account representing the customer to bill.
    customer_account: str | None

    # The customer's address. Until the invoice is finalized, this field will equal
