class InvoicePayment(BaseModel):
    """Invoice Payments represent payments made against invoices. Invoice Payments can
    be accessed in two ways:
    1. By expanding the `payments` field on the
    [Invoice](https://docs.stripe.com/api#invoice) resource.
    2. By using the Invoice Payment retrieve and list endpoints.

    Invoice Payments include the mapping between payment objects, such as Payment Intent,
    and Invoices.
    This resource and its endpoints allows you to easily track if a payment is associated
    with a specific invoice and
    monitor the allocation details of the payments.
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # Amount that was actually paid for this invoice, in cents (or local equivalent). This field
    # is null until the payment is `paid`. This amount can be less than the `amount_requested`
    # if the PaymentIntent’s `amount_received` is not sufficient to pay all of the invoices that
    amount_paid: int | None

    # Amount intended to be paid toward this invoice, in cents (or local equivalent)
    amount_requested: int

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in
    # lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
    currency: str

    # Unique identifier for the object.
    id: str

    # The invoice that was paid.
    invoice: str | Invoice | DeletedInvoice

    # Stripe automatically creates a default InvoicePayment when the invoice is finalized, and
    # keeps it synchronized with the invoice’s `amount_remaining`. The PaymentIntent associated
    # with the default payment can’t be edited or canceled directly.
    is_default: bool

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["invoice_payment"]
    payment: InvoicesPaymentsInvoicePaymentAssociatedPayment

    # The status of the payment, one of `open`, `paid`, or `canceled`.
    status: str
    status_transitions: InvoicesPaymentsInvoicePaymentStatusTransitions


