class PaymentRecord(BaseModel):
    """A Payment Record is a resource that allows you to represent payments that occur on- or
    off-Stripe.
    For example, you can create a Payment Record to model a payment made on a different
    payment processor,
    in order to mark an Invoice as paid and a Subscription as active. Payment Records
    consist of one or
    more Payment Attempt Records, which represent individual attempts made on a payment
    network.
    """

    model_config = ConfigDict(defer_build=True, populate_by_name=True, protected_namespaces=())

    # A representation of an amount of money, consisting of an amount and a currency.
    amount: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_authorized: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_canceled: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_failed: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_guaranteed: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_refunded: PaymentsPrimitivesPaymentRecordsResourceAmount

    # A representation of an amount of money, consisting of an amount and a currency.
    amount_requested: PaymentsPrimitivesPaymentRecordsResourceAmount

    # ID of the Connect application that created the PaymentRecord.
    application: str | None

    # Time at which the object was created. Measured in seconds since the Unix epoch.
    created: int

    # Customer information for this payment.
    customer_details: PaymentsPrimitivesPaymentRecordsResourceCustomerDetails | None

    # Indicates whether the customer was present in your checkout flow during this payment.
    customer_presence: Literal["off_session", "on_session"] | None

    # An arbitrary string attached to the object. Often useful for displaying to users.
    description: str | None

    # Unique identifier for the object.
    id: str

    # ID of the latest Payment Attempt Record attached to this Payment Record.
    latest_payment_attempt_record: str | None

    # If the object exists in live mode, the value is `true`. If the object exists in test mode,
    # the value is `false`.
    livemode: bool

    # Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an
    # object. This can be useful for storing additional information about the object in a
    # structured format.
    metadata: dict[str, str]

    # String representing the object's type. Objects of the same type share the same value.
    object: Literal["payment_record"]

    # Information about the Payment Method debited for this payment.
    payment_method_details: PaymentsPrimitivesPaymentRecordsResourcePaymentMethodDetails | None

    # Processor information associated with this payment.
    processor_details: PaymentsPrimitivesPaymentRecordsResourceProcessorDetails

    # Indicates who reported the payment.
    reported_by: Literal["self", "stripe"]

    # Shipping information for this payment.
    shipping_details: PaymentsPrimitivesPaymentRecordsResourceShippingDetails | None


